const items = $input.all();

// Add engagement score to each item
const scored = items.map(item => {
  const views = Number(item.json.viewCount) || 1;
  const likes = Number(item.json.likeCount) || 0;
  const comments = Number(item.json.commentCount) || 0;

  const engagementScore = (likes + comments) / views;

  return {
    json: {
      ...item.json,
      views,
      likes,
      comments,
      engagementScore
    }
  };
});

// Sort by views (highest = trending)
scored.sort((a, b) => b.json.views - a.json.views);

// Return TOP 10 videos (not just 1) to have backup options
return scored.slice(0, 10);

// 1) Pinecone responses (current node input)
const pineconeItems = $input.all();

// 2) Original video list from "Prepare Pinecone Payload"
const originalItems = $items('Prepare Pinecone Payload', 0).map(i => i.json);

const newVideos = [];

for (let i = 0; i < pineconeItems.length; i++) {
  const pine = pineconeItems[i].json;          // { vectors, namespace, usage }
  const video = originalItems[i].video;        // { videoId, title, stats, ... }

  const vectors = pine.vectors || {};

  // If Pinecone does NOT have this videoId, keep it
  if (!vectors[video.videoId]) {
    newVideos.push({ json: video });
  }
}

// If we filtered out all videos, stop workflow for today
if (newVideos.length === 0) {
  throw new Error('All top videos have already been sent. Skipping today.');
}

return newVideos;

// Take only the FIRST unsent video
const items = $input.all();
return [items[0]];

const video = $('Current Video').first().json;
const transcriptResponse = $input.first().json;

let transcript = transcriptResponse.transcriptionAsText;

if (!transcript && transcriptResponse.transcription) {
  transcript = transcriptResponse.transcription
    .map(seg => seg.subtitle || seg.text || '')
    .join(' ');
}

if (!transcript) {
  transcript = `No transcript available. Using video description:\n\n${video.description}`;
}

// Safety limit
transcript = transcript.substring(0, 8000);

return [{
  json: {
    ...video,
    transcript,
    hasTranscript: !!transcriptResponse.transcriptionAsText
  }
}];

const allInfluencers = [

  { name: "Cole Medin", channelId: "UCMwVTLZIRRUyyVrkjDpn4pA" },
  { name: "AI Uncovered", channelId: "UCUTF61UNExRdjmoK5mXwWfQ" },
  { name: "Matt Wolfe", channelId: "UCbXxLQfYpM8JY6wTZWOrN0A" },
  { name: "ByteByteGo", channelId: "UCZgt6AzoyjslHTC9dz0UoTw" },
  { name: "nicksaraev", channelId: "UCbo-KbSjJDG6JWQ_MTZ_rNA" },
  { name: "Fireship", channelId: "UCsBjURrPoezykLs9EqgamOA" },
  { name: "airevolutionx", channelId: "UC5l7RouTQ60oUjLjt1Nh-UQ" },
  { name: "TheAiGrid", channelId: "UCbY9xX3_jW5c2fjlZVBI4cg" }
];

function shuffle(array) {
  for (let i = array.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [array[i], array[j]] = [array[j], array[i]];
  }
  return array;
}

const shuffled = shuffle([...allInfluencers]);
const selected = shuffled.slice(0, 5);

return selected.map(influencer => ({
  json: influencer
}));

const items = $input.all();
const videos = [];

for (const item of items) {
  for (const video of item.json.items) {
    videos.push({
      json: {
        videoId: video.id.videoId,
        meta: {
          title: video.snippet.title,
          description: video.snippet.description,
          channelTitle: video.snippet.channelTitle,
          publishedAt: video.snippet.publishedAt
        }
      }
    });
  }
}

return videos;

const statsItems = $input.all();
const metaItems = $items("Extract Video IDs1", 0).map(i => i.json);

return statsItems.map((statsItem, index) => {
  const stats = statsItem.json.items?.[0] || {};
  const meta = metaItems[index]?.meta || {};

  return {
    json: {
      videoId: metaItems[index].videoId || "",
      title: meta.title || "",
      description: meta.description || "",
      channelTitle: meta.channelTitle || "",
      publishedAt: meta.publishedAt || "",
      id: stats.id,
      duration: stats.contentDetails?.duration || "",
      viewCount: parseInt(stats.statistics?.viewCount || 0),
      likeCount: parseInt(stats.statistics?.likeCount || 0),
      commentCount: parseInt(stats.statistics?.commentCount || 0)
    }
  };
});

let raw = $input.first().json.text || '';
raw = raw.replace(/```json|```/g, '').trim();

let data;
try {
  data = JSON.parse(raw);
  if (data.summary) {
    // Remove markdown **bold**
    data.summary = data.summary.replace(/\*\*(.*?)\*\*/g, '$1');

    // Convert * bullets to - bullets for consistency
    data.summary = data.summary.replace(/^\* /gm, '- ');

    // Handle escaped newlines (\n) and convert to actual newlines
    data.summary = data.summary.replace(/\\n/g, '\n');
    data.summary = data.summary.replace(/\n/g, '<br>');
    // Clean up any extra spaces
    data.summary = data.summary.trim();
  }
} catch (e) {
  const jsonMatch = raw.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    try {
      data = JSON.parse(jsonMatch[0]);
      if (data.summary) {
        // Same cleanup operations
        data.summary = data.summary.replace(/\*\*(.*?)\*\*/g, '$1');
        data.summary = data.summary.replace(/^\* /gm, '- ');
        data.summary = data.summary.replace(/\\n/g, '\n');
        data.summary = data.summary.trim();
      }
    } catch (e2) {
      data = { 
        title: "Error parsing response", 
        summary: "Could not parse the LLM response. Please try again."
      };
    }
  } else {
    data = { 
      title: "Error: No valid JSON", 
      summary: "LLM did not return valid JSON."
    };
  }
}

const video = $('Process Transcript').first().json;

// Get remaining unsent videos (all except the first one we used)
const remainingVideos = $('Filter Out Sent Videos').all().slice(1).map(i => i.json);

return [{
  json: {
    data,
    metadata: {
      channelTitle: video.channelTitle,
      videoUrl: `https://www.youtube.com/watch?v=${video.videoId}`,
      videoId: video.videoId,
      viewCount: video.viewCount,
      likeCount: video.likeCount,
      commentCount: video.commentCount,
      hasTranscript: video.hasTranscript,
      source: 'YouTube',
      date: new Date().toLocaleDateString('en-GB'),
      remainingVideosCount: remainingVideos.length
    },
    remainingVideos
  }
}];

// Get metadata from Parse LLM Response1
const meta = $('Parse LLM Response1').first().json.metadata;

// Pinecone index dimension
const DIMENSION = 1024;

// Create a dummy vector: all zeros except the first value
const values = Array(DIMENSION).fill(0);
// Pinecone requires at least one non-zero value
values[0] = 1.0;

return [
  {
    json: {
      vectors: [
        {
          id: meta.videoId,
          values,
          metadata: {
            channelTitle: meta.channelTitle,
            date: meta.date,
            source: 'newsletter'
          }
        }
      ]
    }
  }
];

// Just pass through whatever comes in.
// This node is our “source of truth” for the current video.
return $input.all();

// Use the remainingVideos list from Parse LLM Response1
const parsed = $('Parse LLM Response1').first().json;
const remaining = parsed.remainingVideos || [];

if (!remaining.length) {
  throw new Error('No more videos left to try today.');
}

// Take the first remaining video
const nextVideo = remaining[0];

// (Optional) You could also keep remaining.slice(1) if you want more retries later
return [
  {
    json: nextVideo
  }
];

return $input.all().map(item => ({
  json: {
    video: item.json,       // <- Keep your FULL original video data here
    id: item.json.videoId   // <- Pinecone fetch will need this
  }
}));
